"use client";

import { useEffect, useId, useState } from "react";
import { CARD_FRAME as SHARED_CARD_FRAME } from "@/lib/card-frame";
import { CHART_THEMES } from "@/lib/chart-themes";
import { cn } from "@/lib/utils";
import {
  OTHER_LABEL,
  formatPieValue,
  formatShare,
  pieTotal,
  sliceShare,
  summarizePieChart,
} from "@/features/pie-chart/pie-chart-schema";
import type {
  PieChartData,
  PieSlice,
} from "@/features/pie-chart/pie-chart-schema";

export type PieChartCardState = "streaming" | "loading" | "ready" | "error";

export interface PieChartCardProperties {
  readonly state: PieChartCardState;
  /**
  The topic from the tool input, shown before the data arrives.
  */
  readonly topic?: string;
  readonly data?: PieChartData;
  readonly error?: string;
  readonly className?: string;
}

const CARD_FRAME = `${SHARED_CARD_FRAME} w-full max-w-md`;

function titleCase(value: string) {
  return value
    .trim()
    .split(/\s+/u)
    .map((word) => (word ? word.charAt(0).toUpperCase() + word.slice(1) : word))
    .join(" ");
}

/**
This card's colors: the violet ramp, biggest slice strongest, so the eye reads the order before the labels. Every chart card has its own, so a reply with several charts tells them apart at a glance. "Other" is hatched in grey, since it's leftovers rather than a part of its own.
*/
const SLICE_TONES = CHART_THEMES.pie.ramp;
const OTHER_TONE = "text-muted-foreground";

function isOther(slice: PieSlice) {
  return slice.label === OTHER_LABEL;
}

function sliceTone(slice: PieSlice, index: number) {
  return isOther(slice)
    ? OTHER_TONE
    : SLICE_TONES[Math.min(index, SLICE_TONES.length - 1)];
}

const SWATCH_HATCH =
  "bg-[image:repeating-linear-gradient(-45deg,currentColor_0_1px,transparent_1px_3px)]";

/**
The donut in chart units: every slice runs round a circle of this radius, its stroke as thick as the ring.
*/
const VIEW = 100;
const RADIUS = 38;
const RING = 16;
/**
How much the hovered slice's ring thickens, so it lifts out of the donut.
*/
const RING_LIFT = 4;
/**
The background-colored gap cut between slices, in percent of the circle.
*/
const SLICE_GAP = 0.6;
const HATCH_GAP = 3;

/**
How long the donut takes to sweep round once, start to finish. Each slice draws for its share of it, after the slices before it, so it reads as one clockwise stroke.
*/
const SWEEP_MS = 900;

/**
False for the first frame, so the slices start empty and their dash transition sweeps them in.
*/
function useIsDrawn() {
  const [isDrawn, setIsDrawn] = useState(false);
  useEffect(() => {
    const frame = requestAnimationFrame(() => setIsDrawn(true));
    return () => cancelAnimationFrame(frame);
  }, []);
  return isDrawn;
}

interface Arc {
  slice: PieSlice;
  index: number;
  start: number;
  length: number;
}

function arcsOf(slices: readonly PieSlice[], total: number): Arc[] {
  let start = 0;
  return slices.map((slice, index) => {
    const length = sliceShare(slice, total) * 100;
    const arc = { index, length, slice, start };
    start += length;
    return arc;
  });
}

const Donut = ({
  data,
  active,
  onActive,
}: {
  readonly data: PieChartData;
  readonly active: number | null;
  readonly onActive: (index: number | null) => void;
}) => {
  const hatchId = useId();
  const isDrawn = useIsDrawn();
  const total = pieTotal(data);
  const arcs = arcsOf(data.slices, total);
  const center = VIEW / 2;
  const focus = active === null ? null : data.slices[active];
  const [top] = data.slices;
  // Shares already add up to 100%, so the middle leads with the biggest
  // slice instead of a total that says nothing.
  const restingValue = data.scale === "percent" ? top.value : total;
  const restingLabel = data.scale === "percent" ? top.label : "total";

  return (
    <div className="relative size-36 shrink-0">
      <svg
        aria-hidden
        viewBox={`0 0 ${VIEW} ${VIEW}`}
        className="size-full -rotate-90 overflow-visible"
      >
        <defs>
          <pattern
            id={hatchId}
            width={HATCH_GAP}
            height={HATCH_GAP}
            patternUnits="userSpaceOnUse"
            patternTransform="rotate(45)"
          >
            <line
              x1={0}
              y1={0}
              x2={0}
              y2={HATCH_GAP}
              stroke="currentColor"
              strokeWidth={1}
            />
          </pattern>
        </defs>
        {arcs.map(({ slice, index, start, length }) => {
          const visible = Math.max(length - SLICE_GAP, 0.1);
          const isActive = active === index;
          return (
            <circle
              key={slice.label}
              cx={center}
              cy={center}
              r={RADIUS}
              fill="none"
              pathLength={100}
              stroke={isOther(slice) ? `url(#${hatchId})` : "currentColor"}
              strokeWidth={isActive ? RING + RING_LIFT : RING}
              strokeDasharray={`${isDrawn ? visible : 0} 100`}
              strokeDashoffset={-start}
              className={cn(
                "cursor-default transition-[stroke-dasharray,stroke-width,opacity] ease-linear motion-reduce:transition-none",
                sliceTone(slice, index),
                active !== null && !isActive && "opacity-35"
              )}
              style={{
                transitionDelay: `${(start / 100) * SWEEP_MS}ms, 0ms, 0ms`,
                transitionDuration: `${(length / 100) * SWEEP_MS}ms, 200ms, 200ms`,
              }}
              onMouseEnter={() => onActive(index)}
              onMouseLeave={() => onActive(null)}
            />
          );
        })}
      </svg>

      {/* The middle names the whole, or the slice under the pointer. */}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center px-8 text-center"
      >
        <p className="font-mono text-xl leading-7 font-semibold tracking-tighter tabular-nums">
          {focus
            ? formatShare(sliceShare(focus, total))
            : formatPieValue(restingValue, data.scale)}
        </p>
        <p className="text-muted-foreground line-clamp-2 max-w-full text-xs leading-4 break-words">
          {focus?.label ?? restingLabel}
        </p>
      </div>
    </div>
  );
};

const Legend = ({
  data,
  active,
  onActive,
}: {
  readonly data: PieChartData;
  readonly active: number | null;
  readonly onActive: (index: number | null) => void;
}) => {
  const total = pieTotal(data);
  return (
    <ol className="grid w-full min-w-0 grid-cols-[auto_minmax(0,1fr)_auto_2.25rem] content-center gap-x-2 @sm:w-auto @sm:flex-1">
      {data.slices.map((slice, index) => {
        const isActive = active === index;
        return (
          <li
            key={slice.label}
            className="col-span-full grid grid-cols-subgrid"
          >
            <button
              type="button"
              className={cn(
                "focus-visible:ring-ring col-span-full -mx-1.5 grid min-h-6 cursor-default grid-cols-subgrid items-center rounded-sm px-1.5 py-1 text-left text-xs leading-4 transition-[opacity,background-color] duration-200 outline-none focus-visible:ring-2",
                isActive && "bg-muted/70",
                active !== null && !isActive && "opacity-40"
              )}
              onMouseEnter={() => onActive(index)}
              onMouseLeave={() => onActive(null)}
              onFocus={() => onActive(index)}
              onBlur={() => onActive(null)}
            >
              <span
                aria-hidden
                className={cn(
                  "size-2.5 rounded-[2px]",
                  sliceTone(slice, index),
                  isOther(slice) ? SWATCH_HATCH : "bg-current"
                )}
              />
              <span
                className={cn(
                  "text-pretty break-words",
                  index === 0 && "font-semibold"
                )}
              >
                {slice.label}
              </span>
              <span className="text-muted-foreground text-right font-mono tabular-nums">
                {formatPieValue(slice.value, data.scale)}
              </span>
              <span
                className={cn(
                  "text-right font-mono font-medium tabular-nums",
                  index === 0 ? "text-foreground" : "text-muted-foreground"
                )}
              >
                {formatShare(sliceShare(slice, total))}
              </span>
            </button>
          </li>
        );
      })}
    </ol>
  );
};

const PieChartReady = ({ data }: { readonly data: PieChartData }) => {
  const [active, setActive] = useState<number | null>(null);
  return (
    <div className="@container flex flex-col gap-3">
      <header className="flex h-5 min-w-0 items-center">
        <p className="truncate text-sm font-semibold">
          {titleCase(data.topic)}
        </p>
      </header>

      {/* Side by side when the card has room; on a phone the donut sits
          above the legend, so the names get the whole width. */}
      <div className="flex flex-col items-center gap-4 @sm:flex-row @sm:gap-5">
        <Donut data={data} active={active} onActive={setActive} />
        <Legend data={data} active={active} onActive={setActive} />
      </div>

      <footer className="flex items-center justify-between gap-2">
        <p className="text-muted-foreground min-w-0 truncate text-xs">
          {data.label}
          {data.period ? (
            <>
              {" · "}
              <span className="tabular-nums">{data.period}</span>
            </>
          ) : null}
        </p>
      </footer>
    </div>
  );
};

const PieChartError = ({
  topic,
  message = "The figures service didn't respond. Try again in a moment.",
}: {
  readonly topic?: string;
  readonly message?: string;
}) => (
  <div role="alert" className="flex flex-col gap-1">
    <p className="text-sm font-semibold">
      {topic
        ? `Couldn't load a breakdown of ${titleCase(topic)}`
        : "Couldn't load the pie chart"}
    </p>
    <p className="text-muted-foreground text-xs">{message}</p>
  </div>
);

const SKELETON_ROWS = 5;

/**
The card while its data is on the way: the same donut and legend as the ready card, so nothing moves when the figures land. Shows the topic as soon as it's known (with "…" while the model is still writing it).
*/
export const PieChartCardSkeleton = ({
  topic,
  streaming = false,
  className,
}: {
  readonly topic?: string;
  readonly streaming?: boolean;
  readonly className?: string;
}) => (
  <output
    className={cn(CARD_FRAME, "@container flex flex-col gap-3", className)}
  >
    <span className="sr-only">
      {topic ? `Loading a breakdown of ${topic}` : "Loading a pie chart"}
    </span>
    <div aria-hidden className="flex h-5 items-center">
      {topic ? (
        <p className="truncate text-sm font-semibold">
          {titleCase(topic)}
          {streaming ? <span className="text-muted-foreground">…</span> : null}
        </p>
      ) : (
        <div className="bg-muted h-3.5 w-24 animate-pulse rounded" />
      )}
    </div>
    <div
      aria-hidden
      className="flex flex-col items-center gap-4 @sm:flex-row @sm:gap-5"
    >
      <div className="flex size-36 shrink-0 items-center justify-center">
        <div className="border-muted size-[7.5rem] animate-pulse rounded-full border-[1.4rem]" />
      </div>
      <div className="flex w-full min-w-0 flex-col @sm:w-auto @sm:flex-1">
        {Array.from({ length: SKELETON_ROWS }, (_, index) => (
          // The rows are identical placeholders with nothing else to key on.
          <div key={index} className="flex h-6 items-center gap-2">
            <div className="bg-muted size-2.5 animate-pulse rounded-[2px]" />
            <div className="bg-muted h-3 flex-1 animate-pulse rounded" />
            <div className="bg-muted h-3 w-8 animate-pulse rounded" />
          </div>
        ))}
      </div>
    </div>
    <div aria-hidden className="flex h-4 items-center">
      <div className="bg-muted h-3 w-28 animate-pulse rounded" />
    </div>
  </output>
);

export const PieChartCard = ({
  state,
  topic,
  data,
  error,
  className,
}: PieChartCardProperties) => {
  if (state === "error") {
    return (
      <div className={cn(CARD_FRAME, className)}>
        <PieChartError topic={topic} message={error} />
      </div>
    );
  }
  if (state !== "ready" || !data) {
    return (
      <PieChartCardSkeleton
        topic={topic}
        streaming={state === "streaming"}
        className={className}
      />
    );
  }
  return (
    <section
      aria-label={summarizePieChart(data)}
      className={cn(CARD_FRAME, className)}
    >
      <PieChartReady data={data} />
    </section>
  );
};

"use client";

import { useEffect, useState } from "react";
import { PieChartCard } from "@/features/pie-chart/components/pie-chart-card";
import { loadPieChart } from "@/features/pie-chart/pie-chart-requests";
import type { PieChartData } from "@/features/pie-chart/pie-chart-schema";

/**
What came back for one request. A result for a different topic reads as still loading, so a new topic never flashes the old chart.
*/
type Result =
  | { key: string; status: "ready"; data: PieChartData }
  | { key: string; status: "error"; message: string };

export const LivePieChartCard = ({
  topic,
  streaming = false,
}: {
  readonly topic?: string;
  /**
  The model is still writing the card's props.
  */
  readonly streaming?: boolean;
}) => {
  const [result, setResult] = useState<Result | null>(null);
  const requestKey = topic ?? "";

  useEffect(() => {
    let isCancelled = false;
    const run = async (wanted: string) => {
      let next: Result;
      try {
        next = {
          data: await loadPieChart(wanted),
          key: requestKey,
          status: "ready",
        };
      } catch (error) {
        next = {
          key: requestKey,
          message: Error.isError(error) ? error.message : "Pie chart failed.",
          status: "error",
        };
      }
      if (!isCancelled) {
        setResult(next);
      }
    };
    if (!streaming && topic) {
      run(topic);
    }
    return () => {
      isCancelled = true;
    };
  }, [topic, requestKey, streaming]);

  if (streaming || !topic) {
    return <PieChartCard state="streaming" topic={topic} />;
  }
  const current = result?.key === requestKey ? result : null;
  if (current?.status === "ready") {
    return <PieChartCard state="ready" data={current.data} />;
  }
  return current?.status === "error" ? (
    <PieChartCard state="error" topic={topic} error={current.message} />
  ) : (
    <PieChartCard state="loading" topic={topic} />
  );
};

import { z } from "zod";

export const pieChartCatalogEntry = {
  description: `A live pie (donut) chart for questions about how one whole splits into its parts ("what's the US electricity mix by source?", "smartphone market share by vendor", "how is the US federal budget spent?"). Each slice is one part with its share of the whole. The model writes a free-text topic from the user's ask; the card researches the web and draws the slices, biggest first, folding the smallest into "Other". The topic is the card's title, so keep it a short phrase naming the whole and how it's split ("US electricity generation by source"). Never invent the numbers — the card fetches them. Not for categories that don't add up to a whole (the largest economies): that's BarChartCard. Not for change over time: that's AreaChartCard.`,
  props: z.object({
    topic: z
      .string()
      .describe(
        'The whole and how it splits, taken from the user\'s question — e.g. "US electricity generation by source" or "global smartphone market share by vendor".'
      ),
  }),
};

import type { PieChartData } from "@/features/pie-chart/pie-chart-schema";

const sharedPieChartRequests = new Map<
  string,
  { chart: Promise<PieChartData>; expiresAt: number }
>();
const REUSE_MS = 120_000;

function cacheKey(topic: string) {
  return topic.trim().toLowerCase();
}

function pieChartUrl(topic: string) {
  const parameters = new URLSearchParams({ topic });
  return `/api/pie-chart?${parameters}`;
}

async function fetchPieChart(topic: string) {
  const response = await fetch(pieChartUrl(topic));
  const body = (await response.json()) as PieChartData | { error: string };
  if (!response.ok || "error" in body) {
    throw new Error(
      "error" in body
        ? body.error
        : `Pie chart request failed: ${response.status}`
    );
  }
  return body;
}

async function requestPieChart(key: string, topic: string) {
  try {
    return await fetchPieChart(topic);
  } catch (error) {
    sharedPieChartRequests.delete(key);
    throw error;
  }
}

/**
Load a pie chart's figures. Shared, so the thinking steps and the card make one request between them.
*/
export function loadPieChart(topic: string) {
  const key = cacheKey(topic);
  const hit = sharedPieChartRequests.get(key);
  if (hit && Date.now() < hit.expiresAt) {
    return hit.chart;
  }
  const chart = requestPieChart(key, topic);
  sharedPieChartRequests.set(key, {
    chart,
    expiresAt: Date.now() + REUSE_MS,
  });
  return chart;
}

/**
Seed the client cache from a docs recording.
*/
export function primePieChart(topic: string, data: PieChartData) {
  sharedPieChartRequests.set(cacheKey(topic), {
    chart: Promise.resolve(data),
    expiresAt: Infinity,
  });
}

import { listOf } from "@/features/chat/lookup";
import { loadPieChart } from "@/features/pie-chart/pie-chart-requests";
import { hostOf } from "@/lib/url-host";
import type { CardLookup, Source } from "@/features/chat/lookup";

function topicOf(properties: Record<string, unknown>): string {
  return typeof properties.topic === "string" ? properties.topic.trim() : "";
}

function researchSources(result: unknown): readonly Source[] {
  if (!result || typeof result !== "object") {
    return [];
  }
  const { sourceHref, sourceLabel } = result as {
    sourceHref?: unknown;
    sourceLabel?: unknown;
  };
  if (typeof sourceHref !== "string" || !sourceHref) {
    return [];
  }
  const label =
    typeof sourceLabel === "string" && sourceLabel.trim()
      ? sourceLabel.trim()
      : hostOf(sourceHref);
  return [{ href: sourceHref, label }];
}

export const pieChartLookup: CardLookup = {
  intent: (topics) =>
    topics.length === 1
      ? `The breakdown of ${topics[0]}`
      : `The breakdowns of ${listOf(topics)}`,
  load: (properties) => {
    const topic = topicOf(properties);
    return topic
      ? loadPieChart(topic)
      : Promise.reject(
          new Error(
            'Pass a topic, for example "US electricity generation by source".'
          )
        );
  },
  resultSources: researchSources,
  sources: () => [
    {
      href: "https://parallel.ai",
      label: "parallel.ai",
    },
  ],
  subject: (properties) => topicOf(properties) || null,
};

import "server-only";
import {
  createExtractTool,
  createSearchTool,
} from "@parallel-web/ai-sdk-tools";
import { generateText, isStepCount, Output } from "ai";
import {
  MIN_SLICES,
  foldSlices,
  pieChartResultSchema,
} from "@/features/pie-chart/pie-chart-schema";
import type {
  PieChartData,
  PieChartResult,
  PieSlice,
} from "@/features/pie-chart/pie-chart-schema";

/**
Research copies data tables into numbers, so it uses the same model as the other charts' research, separate from the chat model.
*/
const DEFAULT_RESEARCH_MODEL = "anthropic/claude-haiku-5.5";

/**
Tool steps before the model must answer. Step 0 is forced to search and step 1 to extract, so the numbers come from a page rather than memory; without a forced final answer the model keeps digging and returns nothing.
*/
const STEPS = 5;
const TIMEOUT_MS = 55_000;
/**
Parallel serves cached pages by default; an extracted page older than a day is fetched live so a table's newest release isn't missed.
*/
const LIVE_FETCH_MAX_AGE_S = 86_400;

export class PieChartNotFoundError extends Error {
  constructor(topic: string, options?: ErrorOptions) {
    super(`No pie chart figures found for "${topic}".`, options);
    this.name = "PieChartNotFoundError";
  }
}

function researchPrompt(topic: string): string {
  const today = new Date();
  const year = today.getUTCFullYear();

  return `Today is ${today.toISOString().slice(0, 10)}. Find a real public breakdown of one whole into its parts, for a pie chart:

Topic: ${topic}

Requirements:
- One whole split into parts that add up to it: electricity generation by source, market share by company, a budget by category, population by age group.
- Prefer official or well-known sources (national statistics offices, US EIA, IEA, Ember, IDC, Statista summaries, government budgets, company filings).
- Search first, then extract the best URL(s) — a data table, CSV or JSON API, or a report's table — and copy the numbers from it.
- The latest full period, ${year - 1} or ${year} when it's published. Say which period in period.
- List every part the source lists, each in the same unit; keep the source's own "Other" if it has one. The card folds the smallest parts together itself.
- Positive numeric values only, written out in full: when a table is in thousands or millions, multiply it out and leave "millions" out of the label.
- scale: "percent" when the values are shares adding up to about 100, "currency" for money in USD, otherwise "number".
- You have ${STEPS} tool steps, then you must answer from what you extracted.
- If the topic isn't a whole made of parts, fail rather than inventing one.`;
}

function cleanSlices(slices: PieChartResult["slices"]): PieSlice[] {
  const seen = new Set<string>();
  const cleaned: PieSlice[] = [];
  for (const slice of slices) {
    const label = slice.label.trim();
    if (
      !label ||
      !Number.isFinite(slice.value) ||
      slice.value <= 0 ||
      seen.has(label.toLowerCase())
    ) {
      continue;
    }
    seen.add(label.toLowerCase());
    cleaned.push({ label, value: slice.value });
  }
  return foldSlices(cleaned);
}

function toPieChartData(query: string, output: PieChartResult): PieChartData {
  const slices = cleanSlices(output.slices);
  if (slices.length < MIN_SLICES) {
    throw new PieChartNotFoundError(query);
  }
  return {
    asOf: Date.now(),
    fake: false,
    label: output.label.trim() || "Share",
    period: output.period?.trim() || null,
    scale: output.scale,
    slices,
    sourceHref: output.sourceHref ?? undefined,
    sourceLabel: output.sourceLabel ?? undefined,
    topic: query,
  };
}

async function researchOnce(
  query: string,
  abortSignal: AbortSignal
): Promise<PieChartData> {
  const model = process.env.PIE_CHART_MODEL || DEFAULT_RESEARCH_MODEL;
  const webSearch = createSearchTool({
    client_model: model,
    max_results: 8,
    mode: "advanced",
  });
  const webExtract = createExtractTool({
    client_model: model,
    fetch_policy: { max_age_seconds: LIVE_FETCH_MAX_AGE_S },
  });

  const { output } = await generateText({
    abortSignal,
    instructions:
      "You turn questions into honest breakdowns of a whole into its parts for a generative UI pie chart. Never invent, estimate or recall figures from memory: every value must come from a page you extracted.",
    model,
    output: Output.object({ schema: pieChartResultSchema }),
    prepareStep: ({ stepNumber }) => {
      if (stepNumber === 0) {
        return { toolChoice: { toolName: "webSearch", type: "tool" } };
      }
      if (stepNumber === 1) {
        return { toolChoice: { toolName: "webExtract", type: "tool" } };
      }
      return stepNumber >= STEPS ? { toolChoice: "none" } : {};
    },
    prompt: researchPrompt(query),
    stopWhen: isStepCount(STEPS + 1),
    tools: {
      webExtract,
      webSearch,
    },
  });

  if (!output?.slices?.length) {
    throw new PieChartNotFoundError(query);
  }
  return toPieChartData(query, output);
}

async function researchPieChart(query: string): Promise<PieChartData> {
  const abortSignal = AbortSignal.timeout(TIMEOUT_MS);
  try {
    return await researchOnce(query, abortSignal);
  } catch (error) {
    if (abortSignal.aborted) {
      throw error;
    }
    return await researchOnce(query, abortSignal);
  }
}

/**
Research a free-text topic on the web (Parallel search + extract) and shape it into the parts of one whole.
*/
export async function getPieChart(topic: string): Promise<PieChartData> {
  const query = topic.trim();
  if (!query) {
    throw new PieChartNotFoundError(topic);
  }
  if (!process.env.PARALLEL_API_KEY) {
    throw new Error(
      "PARALLEL_API_KEY is missing. Add it to .env.local to load live pie charts."
    );
  }

  try {
    return await researchPieChart(query);
  } catch (error) {
    if (error instanceof PieChartNotFoundError) {
      throw error;
    }
    if (Error.isError(error) && /PARALLEL_API_KEY/u.test(error.message)) {
      throw error;
    }
    throw new PieChartNotFoundError(query, { cause: error });
  }
}

import { z } from "zod";

export const PIE_CHART_SCALES = ["number", "percent", "currency"] as const;
export type PieChartScale = (typeof PIE_CHART_SCALES)[number];

/**
Fewest and most slices the donut draws. One slice is the whole; past six the thin ones can't be told apart, so the rest fold into "Other".
*/
export const MIN_SLICES = 2;
export const MAX_SLICES = 6;

/**
The label of the slice the smallest parts fold into.
*/
export const OTHER_LABEL = "Other";

/**
How sources name their leftovers: "Other", "Others", "All other", "Other providers". A named group like "Other renewables" is a part of its own.
*/
const OTHER_NAMES =
  /^(?:all\s+)?others?(?:\s+(?:providers|vendors|companies|brands|countries|sources))?$/iu;

export interface PieSlice {
  /**
  The part, e.g. "Natural gas" or "Apple".
  */
  label: string;
  value: number;
}

export interface PieChartData {
  /**
  The free-text topic the model (or caller) asked for.
  */
  topic: string;
  /**
  What the values measure, e.g. "Electricity generation (TWh)" or "Market share".
  */
  label: string;
  scale: PieChartScale;
  /**
  The period the breakdown is for, e.g. "2025" or "Q2 2026".
  */
  period: string | null;
  /**
  Biggest first, with "Other" last when small parts were folded together.
  */
  slices: PieSlice[];
  /**
  Unix time in milliseconds of when the figures were looked up.
  */
  asOf: number;
  /**
  True when this is generated data, not live figures.
  */
  fake: boolean;
  /**
  Optional attribution for thinking-step sources.
  */
  sourceHref?: string;
  sourceLabel?: string;
}

/**
Structured answer the research model must return after searching the web.
*/
export const pieChartResultSchema = z.object({
  label: z
    .string()
    .describe(
      'What the values measure in 2–5 words, with the unit in brackets when it isn\'t a share, e.g. "Electricity generation (TWh)" or "Market share". No sources, places or notes: the title has those.'
    ),
  period: z
    .string()
    .nullable()
    .describe('The period the breakdown is for, e.g. "2025", or null.'),
  scale: z
    .enum(PIE_CHART_SCALES)
    .describe(
      "percent when the values are shares of 100, currency for money in USD, otherwise number."
    ),
  slices: z
    .array(
      z.object({
        label: z
          .string()
          .describe('The part\'s short name, 1–3 words, e.g. "Natural gas".'),
        value: z.number(),
      })
    )
    .min(MIN_SLICES)
    .describe(
      "Every part of the whole, as the source lists them, together adding up to the whole. Positive numbers only, written out in full."
    ),
  sourceHref: z
    .string()
    .nullable()
    .describe("Best source URL for the numbers, or null."),
  sourceLabel: z
    .string()
    .nullable()
    .describe("Short source name, e.g. US EIA or IDC."),
});
export type PieChartResult = z.infer<typeof pieChartResultSchema>;

/**
Biggest first, keeping five parts and folding the rest (and any "Other" the source already had) into one "Other" slice, so the donut never has more than six.
*/
export function foldSlices(slices: readonly PieSlice[]): PieSlice[] {
  const isOther = (slice: PieSlice) => OTHER_NAMES.test(slice.label.trim());
  const parts = slices
    .filter((slice) => !isOther(slice))
    .toSorted((a, b) => b.value - a.value);
  const listedOther = slices
    .filter(isOther)
    .reduce((sum, slice) => sum + slice.value, 0);
  const otherSlots = listedOther ? 1 : 0;
  const kept =
    parts.length + otherSlots > MAX_SLICES
      ? parts.slice(0, MAX_SLICES - 1)
      : parts;
  const other =
    listedOther +
    parts.slice(kept.length).reduce((sum, slice) => sum + slice.value, 0);
  return other ? [...kept, { label: OTHER_LABEL, value: other }] : kept;
}

export function pieTotal(data: PieChartData): number {
  return data.slices.reduce((sum, slice) => sum + slice.value, 0);
}

export function sliceShare(slice: PieSlice, total: number): number {
  return total ? slice.value / total : 0;
}

function formatCurrency(value: number): string {
  const formatter = new Intl.NumberFormat("en-US", {
    currency: "USD",
    maximumFractionDigits: 0,
    style: "currency",
  });
  return formatter.format(value);
}

function formatPlain(value: number, maximumFractionDigits: number): string {
  const formatter = new Intl.NumberFormat("en-US", { maximumFractionDigits });
  return formatter.format(value);
}

function numberFractionDigits(absolute: number): number {
  if (absolute >= 100) {
    return 0;
  }
  return absolute >= 10 ? 1 : 2;
}

const MAGNITUDES = [
  { divisor: 1_000_000_000_000, suffix: "T" },
  { divisor: 1_000_000_000, suffix: "B" },
  { divisor: 1_000_000, suffix: "M" },
  { divisor: 1000, suffix: "K" },
] as const;

/**
Values above this read better as "12.3K" than "12,345" in the legend.
*/
const COMPACT_THOUSANDS_FROM = 100_000;

function compactMagnitude(absolute: number) {
  return MAGNITUDES.find(
    ({ divisor }) =>
      absolute >= divisor &&
      (divisor > 1000 || absolute >= COMPACT_THOUSANDS_FROM)
  );
}

const DECIMAL = new Intl.NumberFormat("en-US", { maximumFractionDigits: 1 });

export function formatPieValue(
  value: number,
  scale: PieChartScale,
  isCompact = true
): string {
  if (scale === "percent") {
    return `${DECIMAL.format(value)}%`;
  }
  const absolute = Math.abs(value);
  const magnitude = isCompact ? compactMagnitude(absolute) : undefined;
  if (!magnitude) {
    return scale === "currency"
      ? formatCurrency(value)
      : formatPlain(value, numberFractionDigits(absolute));
  }
  const scaled = value / magnitude.divisor;
  const digits = Math.abs(scaled) >= 100 ? 0 : 1;
  return `${scale === "currency" ? "$" : ""}${scaled.toFixed(digits)}${magnitude.suffix}`;
}

const SHARE_FORMAT = new Intl.NumberFormat("en-US", {
  maximumFractionDigits: 0,
  style: "percent",
});

/**
A slice's share of the whole, e.g. "38%"; anything under half a percent reads "<1%" rather than a misleading "0%".
*/
export function formatShare(share: number): string {
  return share > 0 && share < 0.005 ? "<1%" : SHARE_FORMAT.format(share);
}

/**
One sentence the model (or a screen reader) can use to describe the card.
*/
export function summarizePieChart(data: PieChartData): string {
  const total = pieTotal(data);
  const slices = data.slices.map(
    (slice) =>
      `${slice.label} ${formatShare(sliceShare(slice, total))} (${formatPieValue(slice.value, data.scale, false)})`
  );
  const period = data.period ? ` in ${data.period}` : "";
  return `${data.label}${period}: ${slices.join(", ")}.`;
}

