import {
  PieChartNotFoundError,
  getPieChart,
} from "@/features/pie-chart/pie-chart-queries";

// Research runs for up to 55s (TIMEOUT_MS).
export const maxDuration = 60;

const CACHE = "public, s-maxage=300, stale-while-revalidate=3600";

// eslint-disable-next-line sonarjs/function-name -- Next.js route handlers must be named after the HTTP method
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const topic = searchParams.get("topic")?.trim() ?? "";

  if (!topic) {
    return Response.json(
      {
        error: "Pass a topic, for example US electricity generation by source.",
      },
      { status: 400 }
    );
  }

  try {
    const data = await getPieChart(topic);
    return Response.json(data, {
      headers: { "Cache-Control": CACHE },
    });
  } catch (error) {
    const status = error instanceof PieChartNotFoundError ? 404 : 502;
    return Response.json(
      {
        error: Error.isError(error) ? error.message : "Pie chart failed.",
      },
      { status }
    );
  }
}

/**
The surface every data card shares: the page's own background and text, and one hairline border. Cards with their own shape (a seat map, a ticket stub) take just this.
*/
export const CARD_SURFACE = "bg-background text-foreground border";

/**
The whole frame of a plain data card: the shared surface with 1rem corners and 1rem of padding. Each card adds its own width.
*/
export const CARD_FRAME = `${CARD_SURFACE} rounded-2xl p-4`;

/**
Every chart card draws in its own color, so a reply with several charts never reads as one wall of blue. Each theme is one hue in a few shades, written out as whole Tailwind classes so they survive the build. All of them set the text color: a card paints with `currentColor` (`bg-current`, `stroke="currentColor"`), so one class colors a bar, a line, a ring or a swatch.

Green and red stay out of every theme: the cards keep them for good and bad news (a rise, a loss, a negative bar).
*/
export interface ChartTheme {
  /**
  The leading mark: the top bar, the line, the biggest slice, the first subject.
  */
  solid: string;
  /**
  Everything behind the leader, a step quieter (usually hatched).
  */
  soft: string;
  /**
  Six steps from strongest to faintest, for marks that need telling apart by shade alone (pie slices). In dark mode the strongest is the lightest, so it still leads.
  */
  ramp: readonly [string, string, string, string, string, string];
}

